-- Discount in the plan and automatic monthly generation (owner decisions after US-017). Synthetic data only.
begin;
select plan(22);

insert into auth.users (id, email, raw_user_meta_data) values
 ('00000000-0000-0000-0000-0000000000a1', 'gestor@example.test', '{"display_name":"Gestor Um","birth_date":"1985-05-05"}'),
 ('00000000-0000-0000-0000-0000000000a2', 'gestor2@example.test', '{"display_name":"Gestor Dois","birth_date":"1985-05-05"}'),
 ('00000000-0000-0000-0000-0000000000b1', 'aluno1@example.test', '{"display_name":"Aluno Um","birth_date":"1990-01-01"}'),
 ('00000000-0000-0000-0000-0000000000b2', 'aluno2@example.test', '{"display_name":"Aluno Dois","birth_date":"1990-01-01"}'),
 ('00000000-0000-0000-0000-0000000000b3', 'aluno3@example.test', '{"display_name":"Aluno Tres","birth_date":"1990-01-01"}');
insert into public.academies (id, name, slug, owner_user_id) values
 ('00000000-0000-0000-0000-00000000ac01', 'Academia Um', 'extra-um', '00000000-0000-0000-0000-0000000000a1'),
 ('00000000-0000-0000-0000-00000000ac02', 'Academia Dois', 'extra-dois', '00000000-0000-0000-0000-0000000000a2');
insert into public.memberships (academy_id, user_id, role, status) values
 ('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000a1', 'manager', 'approved'),
 ('00000000-0000-0000-0000-00000000ac02', '00000000-0000-0000-0000-0000000000a2', 'manager', 'approved'),
 ('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b1', 'student', 'approved'),
 ('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b2', 'student', 'approved'),
 ('00000000-0000-0000-0000-00000000ac02', '00000000-0000-0000-0000-0000000000b3', 'student', 'approved');
create temp table ctx as
  select public.academy_today('00000000-0000-0000-0000-00000000ac01') as today,
         date_trunc('month', public.academy_today('00000000-0000-0000-0000-00000000ac01'))::date as month;
grant select on ctx to authenticated;

set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a1","role":"authenticated"}', true);

-- Discount: a fixed amount below the plan value, always with a reason
select lives_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b1', 20000, 10, (select today - 30 from ctx), true, 5000, 'irmaos (teste)')$$, 'plano com desconto e motivo');
select throws_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b2', 20000, 10, (select today - 30 from ctx), true, 5000, null)$$, '22023', null, 'desconto sem motivo rejeitado');
select throws_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b2', 20000, 10, (select today - 30 from ctx), true, 20000, 'bolsa total (teste)')$$, '22023', null, 'desconto igual ao valor rejeitado (cancele ou isente)');
select throws_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b2', 20000, 10, (select today - 30 from ctx), true, -1, 'x')$$, '22023', null, 'desconto negativo rejeitado');
select lives_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac01', '00000000-0000-0000-0000-0000000000b2', 12000, 10, (select today - 30 from ctx), true, 0, 'motivo sem desconto some')$$, 'plano sem desconto');
select is((select discount_note from public.list_member_plans('00000000-0000-0000-0000-00000000ac01') where user_id = '00000000-0000-0000-0000-0000000000b2'), null, 'sem desconto, o motivo nao fica gravado');
select is((select discount_note from public.list_member_plans('00000000-0000-0000-0000-00000000ac01') where user_id = '00000000-0000-0000-0000-0000000000b1'), 'irmaos (teste)', 'a lista de planos mostra o motivo do desconto');
select is((select public.generate_monthly_charges('00000000-0000-0000-0000-00000000ac01', (select month from ctx), gen_random_uuid())), 2, 'gera as duas mensalidades');
select is((select amount_cents from public.charges where user_id = '00000000-0000-0000-0000-0000000000b1'), 15000, 'a cobranca sai com o valor ja descontado');
select is((select discount_cents from public.charges where user_id = '00000000-0000-0000-0000-0000000000b1'), 5000, 'e registra quanto foi o desconto');

-- Automatic generation: the manager turns it on; only a flagged academy is generated by the daily job
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000b1","role":"authenticated"}', true);
select throws_ok($$select public.set_auto_charges('00000000-0000-0000-0000-00000000ac01', true)$$, '42501', null, 'aluno nao liga a geracao automatica');
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a2","role":"authenticated"}', true);
select throws_ok($$select public.set_auto_charges('00000000-0000-0000-0000-00000000ac01', true)$$, '42501', null, 'gestor de outra academia nao liga');
select throws_ok($$select public.run_auto_charges()$$, '42501', null, 'o job diario nao e chamavel por clientes');
select lives_ok($$select public.set_member_plan('00000000-0000-0000-0000-00000000ac02', '00000000-0000-0000-0000-0000000000b3', 9000, 5, (select today - 30 from ctx), true, 0, null)$$, 'plano na academia dois');
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a1","role":"authenticated"}', true);
select lives_ok($$select public.set_auto_charges('00000000-0000-0000-0000-00000000ac01', true)$$, 'gestor liga a geracao automatica');
select is((select auto_charges from public.academies where id = '00000000-0000-0000-0000-00000000ac01'), true, 'ligada na academia um');

-- The job (as the scheduler runs it: no user session)
reset role;
update public.charges set status = 'cancelled', status_note = 'preparo do teste' where user_id = '00000000-0000-0000-0000-0000000000b2';
delete from public.charge_events where charge_id in (select id from public.charges where user_id = '00000000-0000-0000-0000-0000000000b2');
delete from public.charges where user_id = '00000000-0000-0000-0000-0000000000b2';
select is(public.run_auto_charges(), 1, 'o job gera so a mensalidade que faltava (a academia dois nao esta ligada)');
select is(public.run_auto_charges(), 0, 'rodar de novo nao duplica');
select is((select count(*)::int from public.charges where user_id = '00000000-0000-0000-0000-0000000000b3'), 0, 'academia sem a opcao ligada nao e gerada');
select is((select count(*)::int from public.audit_events where action = 'finance.generate' and metadata ->> 'auto' = 'true'), 1, 'a geracao automatica fica marcada na auditoria');
select is((select count(*)::int from cron.job where jobname = 'auto-charges' and active), 1, 'o agendamento diario existe e esta ativo');
select is((select count(*)::int from public.charges where reference_month = (select month from ctx)), 2, 'duas mensalidades no mes, sem duplicar');

select * from finish();
rollback;
